import pandas as pd
f='/home/beeps/.local/share/idli-bench/codex/offset_headers.q6.codex.0/ws/programme_monthly_spend.xlsx'
df_raw=pd.read_excel(f, sheet_name='Monthly Spend', header=None)
data=[]
for i in range(5,17):
    row=df_raw.iloc[i]
    prog_code=row[0]
    if pd.isna(prog_code):
        continue
    funding=row[3]
    # columns 4-9
    vals=[]
    for col in [4,5,6,7,8,9]:
        v=row[col]
        if pd.isna(v):
            vals.append(0)
        elif isinstance(v,str):
            if v.strip() in ['-','–','']:
                vals.append(0)
            else:
                try:
                    vals.append(float(v.replace(',','')))
                except:
                    vals.append(0)
        else:
            vals.append(float(v))
    data.append((funding, sum(vals)))
from collections import defaultdict
sums=defaultdict(float)
for fnd, s in data:
    sums[fnd]+=s
for k,v in sorted(sums.items(), key=lambda x:x[1], reverse=True):
    print(k, int(v))
